<script setup lang="ts">
import { ref, watch } from 'vue'
import { toast } from 'vue-sonner'
import { Dialog,DialogContent,DialogHeader,DialogTitle,DialogDescription,DialogFooter } from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Select, SelectTrigger, SelectValue, SelectContent, SelectGroup, SelectItem } from '@/components/ui/select'
import { Switch } from '@/components/ui/switch'
import { call,message } from '@/services/api'
import { useWorkbench } from '@/stores/workbench'
const props=defineProps<{open:boolean;kind:'history'|'conflict'|'backups'|'format'}>(),emit=defineEmits<{'update:open':[boolean]}>(),store=useWorkbench()
const operations=ref<any[]>([]),encoding=ref('UTF-8'),bom=ref(false),crlf=ref(false),rows=ref<any[]>([]),selected=ref(''),text=ref(''),baseline=ref(''),expectedHash=ref(''),error=ref(''),busy=ref(false),documentId=ref(''),backupWorkspace=ref('')
async function load(){error.value='';rows.value=[];selected.value='';text.value='';busy.value=true;const d=store.active;documentId.value=d?.id||'';baseline.value=d?.text||'';try{if(props.kind==='backups'){if(!store.workspaces.some(w=>w.id===backupWorkspace.value))backupWorkspace.value=d&&!d.workspaceId.startsWith('file-')?d.workspaceId:store.workspaces.find(w=>!w.id.startsWith('file-'))?.id||'';if(backupWorkspace.value)rows.value=await call('list_workspace_backups',{workspaceId:backupWorkspace.value});operations.value=await call('list_operation_backups')}else if(d){if(props.kind==='history'){rows.value=await call('list_versions',{documentId:d.id});if(rows.value[0])await choose(rows.value[0])}else{const disk=await call<{text:string;hash:string;encoding:string;bom:boolean;crlf:boolean}>('read_disk_document',{documentId:d.id});text.value=disk.text;expectedHash.value=disk.hash;encoding.value=disk.encoding;bom.value=disk.bom;crlf.value=disk.crlf}}}catch(e){error.value=message(e)}finally{busy.value=false}}
async function choose(row:any){selected.value=row.id;try{text.value=(await call<{text:string}>('read_version',{documentId:documentId.value,id:row.id})).text}catch(e){error.value=message(e)}}
async function apply(merge=false){const d=store.active;if(!d||d.id!==documentId.value||d.text!==baseline.value){error.value='文档已变化，请重新打开此窗口。';return}busy.value=true;try{await call('snapshot_document',{documentId:d.id,text:d.text,reason:props.kind==='history'?'恢复前':'合并前'});if(props.kind==='history'){store.change(d,text.value,'restore');d.generation++}else{if(merge){store.change(d,text.value,'merge');d.generation++}await store.overwrite(d,expectedHash.value)}emit('update:open',false)}catch(e){error.value=message(e)}finally{busy.value=false}}
async function backup(){if(!backupWorkspace.value)return;busy.value=true;error.value='';try{if(!await store.flush(backupWorkspace.value))throw new Error('请先处理未保存或冲突内容。');await call('backup_workspace',{workspaceId:backupWorkspace.value});await load();toast.success('工作区备份已完成')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function restoreOperation(row:any){busy.value=true;error.value='';try{if(!await store.flush())throw new Error('请先处理未保存内容');const result=await call<{tags?:string[];drafts?:any[]}>('restore_operation_backup',{id:row.id});if(result.tags)store.preferences.tags=result.tags;if(result.drafts)store.drafts.push(...result.drafts.filter(row=>!store.drafts.some(d=>d.id===row.id)));else for(const d of store.documents)await store.reload(d);await store.refresh();await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function convert(){const d=store.active;if(!d||d.id!==documentId.value||d.text!==baseline.value){error.value='文档已变化，请重新打开';return}busy.value=true;try{if(!await store.save(d))throw new Error('请先解决保存问题');const disk=await call<any>('convert_document_format',{documentId:d.id,expectedHash:d.hash,encoding:encoding.value,bom:bom.value,crlf:crlf.value});Object.assign(d,disk);emit('update:open',false)}catch(e){error.value=message(e)}finally{busy.value=false}}
watch(()=>props.open,v=>{if(v)void load()})
</script>
<template><Dialog :open="open" @update:open="v=>{if(!busy)emit('update:open',v)}"><DialogContent class="productivity-dialog flex max-h-[calc(100dvh-48px)] flex-col sm:max-w-5xl"><DialogHeader><DialogTitle>{{kind==='history'?'历史版本':kind==='conflict'?'比较与合并磁盘版本':kind==='format'?'编码与换行格式':'工作区备份'}}</DialogTitle><DialogDescription>{{kind==='history'?'预览历史内容。恢复会保留当前版本，并支持撤销。':kind==='conflict'?'左侧为当前内容，右侧为磁盘版本；可编辑右侧作为合并结果。保存前再次验证磁盘是否变化。':'备份包含文档和附件，按保留数量管理；可打开目录查看完整副本。'}}</DialogDescription></DialogHeader><p v-if="error" role="alert" class="text-sm text-destructive">{{error}}</p><p v-if="busy" role="status">处理中…</p><div v-if="kind==='format'" class="flex flex-col gap-4"><p class="text-sm">转换前会保存原始字节备份。UTF-16 始终写入 BOM。</p><div class="flex items-center justify-between gap-3"><span>编码</span><Select v-model="encoding"><SelectTrigger aria-label="文档编码" class="w-40"><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem value="UTF-8">UTF-8</SelectItem><SelectItem value="UTF-16LE">UTF-16LE</SelectItem><SelectItem value="UTF-16BE">UTF-16BE</SelectItem></SelectGroup></SelectContent></Select></div><div class="flex items-center justify-between gap-3"><span>UTF-8 BOM</span><Switch v-model="bom" :disabled="encoding!=='UTF-8'" aria-label="写入 UTF-8 BOM"/></div><div class="flex items-center justify-between gap-3"><span>使用 CRLF 换行</span><Switch v-model="crlf" aria-label="使用 CRLF 换行"/></div></div><div v-else-if="kind==='backups'" class="flex min-h-0 flex-col gap-3 overflow-auto"><div class="flex items-center justify-between gap-3"><span>备份工作区</span><Select :model-value="backupWorkspace" @update:model-value="v=>{backupWorkspace=typeof v==='string'?v:'';load()}"><SelectTrigger aria-label="备份工作区" class="w-80 max-w-full"><SelectValue/></SelectTrigger><SelectContent><SelectGroup><SelectItem v-for="ws in store.workspaces.filter(w=>!w.id.startsWith('file-'))" :key="ws.id" :value="ws.id">{{ws.name}}</SelectItem></SelectGroup></SelectContent></Select></div><Button :disabled="busy||!backupWorkspace" @click="backup">立即备份工作区</Button><Button variant="outline" @click="call('open_backup_directory').catch(e=>error=message(e))">打开备份目录</Button><div v-for="row in rows" :key="row.path" class="rounded-lg border p-3 text-sm"><p>{{new Date(row.createdAt*1000).toLocaleString()}} · {{row.files}} 个文件</p><p class="break-all text-xs text-muted-foreground">{{row.path}}</p></div><p v-if="!rows.length&&!busy" class="text-sm text-muted-foreground">还没有备份。点击上方按钮创建第一份副本。</p><h3 class="text-sm font-medium">可恢复的批量操作</h3><div v-for="row in operations" :key="row.id" class="flex items-center justify-between gap-3 rounded-lg border p-3"><span class="text-sm">{{row.kind==='tags'?'批量标签修改':row.kind==='draft'?'丢弃的恢复草稿':row.kind==='delete'?'文件或目录删除':'编码转换'}} · {{new Date(row.createdAt*1000).toLocaleString()}}</span><Button variant="outline" :disabled="busy||!!row.restoredAt" @click="restoreOperation(row)">{{row.restoredAt?'已恢复':'恢复操作前内容'}}</Button></div></div><div v-else class="flex min-h-0 flex-1 gap-3 max-sm:flex-col"><nav v-if="kind==='history'" class="flex max-h-96 w-44 shrink-0 flex-col gap-1 overflow-auto max-sm:w-full"><Button v-for="row in rows" :key="row.id" :variant="selected===row.id?'secondary':'ghost'" class="h-auto justify-start whitespace-normal text-left" @click="choose(row)"><span>{{new Date(row.createdAt).toLocaleString()}}<small class="block text-muted-foreground">{{row.reason}} · {{row.size}} 字节</small></span></Button><p v-if="!rows.length&&!busy" class="text-sm text-muted-foreground">保存文档后会生成历史版本。</p></nav><div class="grid min-w-0 flex-1 grid-cols-2 gap-3 max-sm:grid-cols-1"><div class="flex min-w-0 flex-col gap-2"><span class="text-sm font-medium">当前版本</span><Textarea :model-value="baseline" readonly aria-label="当前版本内容" class="h-80 resize-none font-mono text-xs" /></div><div class="flex min-w-0 flex-col gap-2"><span class="text-sm font-medium">{{kind==='history'?'历史版本':'磁盘版本 / 合并结果'}}</span><Textarea v-model="text" :readonly="kind==='history'" aria-label="版本比较内容" class="h-80 resize-none font-mono text-xs" /></div><p class="col-span-full text-xs text-muted-foreground">{{baseline===text?'内容相同':'内容存在差异'}} · 当前 {{baseline.length}} 字符 / 对比 {{text.length}} 字符</p></div></div><DialogFooter><Button variant="outline" :disabled="busy" @click="emit('update:open',false)">关闭</Button><Button v-if="kind==='format'" :disabled="busy" @click="convert">备份并转换格式</Button><Button v-if="kind==='history'" :disabled="busy||!selected" @click="apply()">恢复此版本</Button><template v-if="kind==='conflict'"><Button variant="outline" :disabled="busy" @click="apply()">保留当前版本并备份磁盘</Button><Button :disabled="busy" @click="apply(true)">保存右侧合并结果</Button></template></DialogFooter></DialogContent></Dialog></template>
